const {chromium}=require('playwright'),fs=require('fs'),path=require('path'),assert=require('node:assert/strict');
(async()=>{const browser=await chromium.launch({channel:'chrome',headless:true});try{
 const page=await browser.newPage();await page.route('https://recovery.test/**',r=>r.fulfill({contentType:'text/html',body:'<div id="composer"></div>'}));await page.goto('https://recovery.test');const root=path.join(__dirname,'../web');await page.addScriptTag({content:fs.readFileSync(path.join(root,'js/05-components.js'),'utf8')});
 await page.evaluate(()=>{window.chatSyncedDrafts=new Map();window.chatBaseFor=a=>'/api/agents/chat/'+a+'/sessions';window.chatDraftKey='codex/new';window.chatOpenId='';window.chatStateEqual=(a,b)=>JSON.stringify(a)===JSON.stringify(b);});
 const src=fs.readFileSync(path.join(root,'js/48-chat.js'),'utf8');await page.addScriptTag({content:src.slice(src.indexOf('const chatDeliveryStorageKey ='),src.indexOf('function chatAddSharedTerminal('))});
 await page.evaluate(()=>{chatWriteDeliveryOutbox([{agent:'codex',scope:'codex/abcdef123456',draftScope:'codex/new',url:'/api/terminal/session/abcdef123456/input',payload:{requestId:'request-123456',text:'Earlier coding request'}}]);chatRenderDeliveryNotice(document.getElementById('composer'),'codex/new');});
 assert.equal(await page.locator('.chat-delivery-notice').count(),0);assert.equal(await page.evaluate(()=>chatReadDeliveryOutbox().length),1,'hidden is not discarded');
 await page.evaluate(()=>chatRenderDeliveryNotice(document.getElementById('composer'),'codex/abcdef123456'));await page.locator('summary').click();await page.getByText('Send not confirmed: Earlier coding request',{exact:true}).waitFor();
 await page.evaluate(()=>{window.chatDeliverRemembered=async()=>{throw Error('unconfirmed')}});await page.getByRole('button',{name:'Retry same send'}).click();await page.getByText('Send not confirmed: Earlier coding request',{exact:true}).waitFor();assert.match(await page.locator('[role=status]').textContent(),/still unconfirmed/);
 await page.getByRole('button',{name:'Dismiss notice',exact:true}).click();await page.getByRole('button',{name:'Cancel',exact:true}).click();assert.equal(await page.evaluate(()=>chatReadDeliveryOutbox().length),1);
 await page.getByRole('button',{name:'Dismiss notice',exact:true}).click();await page.getByRole('dialog').getByRole('button',{name:'Dismiss notice',exact:true}).click();assert.equal(await page.locator('.chat-delivery-notice').count(),0);assert.equal(await page.evaluate(()=>chatReadDeliveryOutbox().length),0);
 await page.evaluate(()=>{chatWriteDeliveryOutbox([{agent:'alfred',scope:'alfred/new',url:'/api/agents/chat/alfred/sessions',payload:{requestId:'request-abcdef',text:'Uncreated conversation'}}]);chatRenderDeliveryNotice(document.getElementById('composer'),'alfred/new');});assert.equal(await page.locator('.chat-delivery-notice').count(),1,'genuine unconfirmed creation remains recoverable');
 console.log('PASS recovery notices: conversation scoping, preserved preview, cancel and dismiss, unresolved new-chat recovery.');
 }finally{await browser.close()}})().catch(e=>{console.error(e);process.exit(1)});
